  </head>
  <body>
    <main class="page">
      <div id="app"></div>
    </main>

    <script>
      const state = {
        values: {
          fullName: "",
          email: "",
          phone: "",
        },
        errors: {},
        submitted: false,
        success: false,
      };

      function TextField({
        id,
        label,
        type = "text",
        value,
        required = false,
        placeholder = "",
        helperText = "",
        error = "",
        autocomplete = "",
      }) {
        const describedBy = [helperText ? `${id}-help` : "", error ? `${id}-error` : ""]
          .filter(Boolean)
          .join(" ");

        return `
          <div class="form-field">
            <label for="${id}">${label}${required ? '<span class="required-mark" aria-hidden="true"> *</span>' : ""}</label>
            <input
              id="${id}"
              name="${id}"
              type="${type}"
              value="${escapeHtml(value)}"
              placeholder="${placeholder}"
              ${required ? "required" : ""}
              ${autocomplete ? `autocomplete="${autocomplete}"` : ""}
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
              aria-invalid="${error ? "true" : "false"}"
            />
            ${helperText ? `<p class="helper-text" id="${id}-help">${helperText}</p>` : ""}
            ${error ? `<p class="error-text" id="${id}-error">${error}</p>` : ""}
          </div>
        `;
      }

      function ContactForm() {
        return `
          <section class="card" aria-labelledby="support-form-title">
            <div class="card-header">
              <p class="eyebrow">Support</p>
              <h1 id="support-form-title">Contact our team</h1>
              <p class="subtitle">Send us your details and we&apos;ll get back to you as soon as possible.</p>
            </div>

            <form novalidate>
              <div class="form-grid">
                ${TextField({
                  id: "fullName",
                  label: "Full name",
                  value: state.values.fullName,
                  required: true,
                  placeholder: "Jane Doe",
                  autocomplete: "name",
                  error: state.submitted ? state.errors.fullName || "" : "",
                })}

                ${TextField({
                  id: "email",
                  label: "Email address",
                  type: "email",
                  value: state.values.email,
                  required: true,
                  placeholder: "jane@company.com",
                  autocomplete: "email",
                  error: state.submitted ? state.errors.email || "" : "",
                })}

                ${TextField({
                  id: "phone",
                  label: "Phone number",
                  type: "tel",
                  value: state.values.phone,
                  placeholder: "+1 (555) 123-4567",
                  autocomplete: "tel",
                  helperText: "Optional. Use a format like +1 (555) 123-4567 or 555-123-4567.",
                  error: state.submitted ? state.errors.phone || "" : "",
                })}
              </div>

              <div class="actions">
                <button type="submit">Send message</button>
              </div>

              ${state.success ? '<p class="status" role="status">Thanks — your message has been sent.</p>' : ""}
            </form>
          </section>
        `;
      }

      function validate(values) {
        const errors = {};

        if (!values.fullName.trim()) {
          errors.fullName = "Full name is required.";
        }

        if (!values.email.trim()) {
          errors.email = "Email address is required.";
        } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email.trim())) {
          errors.email = "Enter a valid email address.";
        }

        if (values.phone.trim() && !/^[0-9()+\-\s.]{7,}$/.test(values.phone.trim())) {
          errors.phone = "Enter a valid phone number.";
        }

        return errors;
      }

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      function render() {
        document.getElementById("app").innerHTML = ContactForm();
        bindEvents();
      }

      function bindEvents() {
        const form = document.querySelector("form");
        form.addEventListener("submit", (event) => {
          event.preventDefault();
          state.submitted = true;
          state.errors = validate(state.values);
          state.success = Object.keys(state.errors).length === 0;
          render();
        });

        ["fullName", "email", "phone"].forEach((field) => {
          const input = document.getElementById(field);
          input.addEventListener("input", (event) => {
            state.values[field] = event.target.value;
          });
        });
      }

      render();
    </script>
